        "title": "E245 对话经济学家朱宁：1929之后，我们学会避免下一场经济危机了吗？",
        "desc": "🫧 忘却的代价，永远大于记忆的代价。 \n\n欢迎来到《知行小酒馆》，这是一档由有知有行出品的播客节目，我们关注投资，更关注怎样更好地生活。我是雨白。\n一个多月前，我和家里长辈闲聊，她突然特别严肃地问我： “你知道吗？那个谁谁谁说，今年年底会发生一场全球性的金融危机，规模堪比 2008 年” ，我非常惊讶，问她是从哪里听说的，结果聊了半天，她也没说清楚这个人到底是干嘛的，更不知道他怎么推导出金融危机这个结论。这件事让我印象很深。\n我讲这个故事，不是为了奚落家里人。因为我们大部分人面对财经信息的时候，可能都是这个状态。\n每天，我们的心情会被各种消息来回拉扯：一会儿怕错过泡沫，一会儿又怕危机真的来了。太多的碎片信息，让我们很难判断，真正的危机离我们有多远，更不知道它最后会怎么影响到自己的生活。\n正是在这个时候，我读到了安德鲁·索尔金的新书 《1929》 。 这本书虽然写的是近一百年前的金融危机，可读起来却意外地和我们的当下形成了很多呼应。 \n于是，我们请来了这本书的译者，也是小酒馆的老朋友，经济学家、行为金融学者朱宁教授。 他长期研究泡沫、投资者心理和金融危机。在这期节目中，我们会以 1929 这一历史事件作为起点，但不会停在1929。我们想聊清楚——\n泡沫为什么会形成？为什么很多聪明、理性，甚至知道泡沫存在的人，还是相信自己可以及时离场？ 为什么有些股市大跌，最后只是让投资者亏钱；有些却会继续变成银行出事、企业裁员，最后影响到一个从来不炒股的普通人？ \n把这些问题聊清楚以后，我们再回过头来看今天： 市场里到底正在发生什么？有哪些风险可能正在积累？它们有没有可能串联到一起？ 以及，面对一个谁也无法准确预测的市场，我们普通人该怎么保护好自己和家庭的财富？\n🔗 官方地址\n如果你所使用的客户端显示不全，请点此访问有知有行的官网查看全文 \n🍻 本期嘉宾\n朱宁： 经济学家，上海交通大学上海高级金融学院讲席教授，美国耶鲁大学国际金融中心教授研究员，著有《刚性泡沫》《投资者的敌人》《投资者的朋友》，译著 《1929》 。\n🪡 时间轴\n04:20 「大家都怕股灾，但大家都不怕股灾前面的那个泡沫」\n16:50 在 1929 年的股灾之前，当时的社会已经积蓄了很多的不满与不安 \n22:11 百年前的金融创新与金融「普惠」：分期付款，让普通人像买冰箱一样买股票\n25:08 最美好的夏天还没过完，就爆仓了：韩国年轻人的黄金时代，有点动荡\n29:31 回看历史，几乎每一次跨时代的技术变革，都伴随着一场股市的泡沫 \n35:46 「任何一次危机爆发，你要解决的永远是流动性与信心的问题」\n46:49 泡沫的五个必要而不充分条件 \n50:53 「如果你不惜一切代价去拥抱一次技术创新，很可能你就是那个代价」\n01:07:09 忘却的代价，永远大于记忆的代价 \n📑 猜你想看\n01:26 《1929》 ：由美国财经记者 安德鲁·索尔金 所著，以 1929 年华尔街股灾为中心，讲述此前的投机繁荣、股市崩盘，以及危机如何进一步冲击银行、企业和普通人的生活。\n01:32 《大而不倒》 ：安德鲁·索尔金 记录 2008 年金融危机的作品，主要讲述雷曼兄弟倒闭前后，美国政府、监管者和华尔街大型金融机构如何试图阻止金融体系崩溃。\n04:15 熔断 ：当市场价格触及预设的异常波动阈值时，交易所按照规则暂时停止交易，为市场参与者提供消化信息和重新评估风险的时间。\n05:48 抽贷 ：银行提前收回已经借出去的钱，或者减少对企业的贷款。危机中，如果很多银行同时抽贷，企业可能因为现金流危机而无法正常经营。\n05:54 续贷 ：一笔贷款到期后，银行重新向借款人发放贷款，使其可以继续使用资金。\n17:49 查尔斯·米切尔 ：美国银行家，曾执掌花旗银行的前身——纽约国民城市银行。他曾大力推动证券销售和普通公众参与股票市场，是《1929》中观察金融创新与投机繁荣的重要人物。\n18:16 咆哮的二十年代 ：通常指第一次世界大战结束后至 1929 年股灾前，以美国为代表的经济和消费繁荣时期。\n19:10 《凡尔赛条约》 ：第一次世界大战结束后签署的和平条约，对战败国德国提出了领土、军事和赔款等要求。\n20:38 斐迪南大公遇刺事件 ：1914 年 6 月 28 日，奥匈帝国王位继承人 弗朗茨·斐迪南大公 在萨拉热窝遇刺。此事触发了欧洲列强之间的「七月危机」，成为第一次世界大战爆发的直接导火索。\n21:09 魏玛共和国恶性通胀 ：德国魏玛共和国在 1923 年经历的货币急剧贬值和物价失控。一战后德国为支付巨额赔款大量印钞，1922—1923 年物价彻底失控，德国马克对美元的汇率从战前的 4.2 跌到 4.2 万亿。\n21:22 金本位 ：指货币价值与一定数量黄金挂钩，并按照固定比率兑换的货币制度。\n",
