        "desc": "本期节目是我六月离开纽约前，做客725沙龙的活动实录。\n大家好，我是大卫翁，\"起朱楼宴宾客\"是我用来记录这个大时代的播客节目。\n这期节目是我在美国访学期间参加的最后一场活动。我和 纽约漫谈录 的主理人欧阳斌老师聊了对于纽约乃至美国的观感，穿梭在几个国度之间生活的一些感受，以及稍微形而上一些的话题，比如作为一个悲观主义者如何在乱纪元里找到生活的锚点。\n回听的时候感觉确实是一场漫谈，但作为我在美国这接近一年时间的总结也恰如其分。\n也欢迎在美国的听友关注725沙龙的线下活动，以及他们的衍生播客节目纽约漫谈录，算得上是纽约华人的一片精神家园。\nPart.1 纽约印象 \n02:00 纽约给我的文化冲击：便利店的柜子竟然是锁着的？\n05:10 在纽约跟100位听友coffee chat 的目标，完成了！\n10:10 一位50多岁的听友把纽约比作一盘“沙拉”：看起来是个整体，但族群、阶层和社群之间依然界限分明\nPart.2 中国、日本、美国的社会差异 \n11:00 日本是一个“活在过去”的社会，很多生活方式与二三十年前相比变化不大\n12:15 美国同时容纳着过去、现在和未来，是一个非常割裂的社会\n13:05 中国呈现出很强的未来感，即便是二三线城市，也在积极引入新科技企业\n15:15 全球化是否已经结束？生活在美国、日本的华人未来还有“希望”吗？\n21:30 为什么大家对出国看看的兴趣越来越低了？因为已经不知道还要出来看什么\n24:00 我们这一代人有一个根深蒂固的价值观：应该去看世界、拥抱世界\nPart.3 从金融白领到内容创作者 \n26:40 为什么我决定离开金融行业？\n35:00 过去我更倾向于保留负面评论，现在遇到涉及人身攻击的评论，我会直接删除\n39:30 我做内容唯一的目的就是获得情绪价值，这些评论和互动，陪伴我度过了在镰仓独居的两年\nPart.4 关于“乱纪元” \n42:07 经常在播客里提到的“乱纪元” ，到底是什么意思？\n47:00 普通人怎么才能不错过时代带来的红利？\n54:00 投资是反人性的，多经历几个周期，才能更好地抵御人性的弱点\n58:10 投资是你对世界观的投票，而我的世界观是——万物皆有周期\nPart.5 问答环节 \n60:10 你是如何应对资产配置中的汇率风险？\n63:20 在时代巨变之下，什么是最重要、最不容易改变的底层能力？\n67:00 如何进行深度学习和对抗信息焦虑？\n欢迎关注我的新书《资产配置行动指南》，解读和购买链接在这里： 158. 播客里聊了四年的资产配置，我把它做成了一本《行动指南》 \n欢迎订阅我的Substack频道，它是一个以英文为主的频道： hubris2025.substack.com \n欢迎关注我和雨白、小跑新制作的时事聊天节目 《不熄灯Lights On》 \n欢迎关注我的生活方式类节目《犬生活》， 《纽约有一种气质叫“都行”｜和杨蒙恩的临别闲聊局》 最新上线！\n欢迎加入我的 知识星球 ，我正在好好运营那一片后花园。\n欢迎在评论区互动，或者给我写邮件，邮箱地址qizhulouyanbinke@gmail.com。\n节目BGM：\nJodymoon - the long way around\nIn The Pool - In The Sea - Chainsaw Man\n节目后期：纽约漫谈录",
