        "desc": "我和易立竞认识很多年，即是朋友也是合作伙伴。她是顶尖的深度人物访谈记者，也是我见过最享受独处的人，能在山里一待就是一个月。而我似乎永远在折腾，腿瘸着、被跳蚤咬了一堆包，还能蜷在轮椅上想创业项目。我俩几乎是人类社交光谱的两极。她追问我的脆弱，我也看见她的世界。在这极致反差里，我们找到了同一种东西：对真相的好奇，以及诚恳面对自己的勇气。两种活法，或许殊途同归。\n00:40 活着是什么？什么叫“自由的活着”？\n02:18 易老师谈社交恐惧——“Small talk对我来说很恐怖”\n03:42 易立竞：深度人物访谈呈现的不是真相，而是人的复杂性\n09:23 拒绝做采访课的原因是不能辜负被采访者的信任\n11:50 各自的一个月独处：山里荡秋千笑出声来&amp;受尽人间疾苦奔溃大哭\n16:55 天真坐轮椅后的“弱者视角”察觉：物理高度变了，看世界的方式也变了\n22:45 “观察着自己的自己又是谁？”关于觉知力、上帝视角，以及人生修行的训练\n24:44 马伊琍的点醒：你讲的都对，但对方一句都听不见\n26:36 杨天真：我以为我很会倾听，其实我不会\n29:22 从“采取报复”到控制欲的减弱：为什么要走那条探索真我的更难的路？\n35:14 天真对陌生人的“零心理障碍”与罕见害羞时刻\n37:02 “我不想显得对谁很在意”——关于决绝选择的心理坦白\n39:22 “谎言是在人世间行走特别有效的拐杖”\n42:20 “人间观察的隐身草”vs“高配得的存在感”——互为反义词的两个人\n55:10 易立竞：我应该有的生活是在大山大海和星星月亮之间\n59:05 两种能量分配方式：把工作当作品 vs 有取舍地投入精力\n64:11 “教唆”易老师开播客的说服现场\n66:02 杨天真：我不会思考失败，我就觉得我能成\n77:58 易老师分享所看见的00后守墓人的两个感人故事\nBGM：《InYourArmsAgain》\n\n/关于《杨天真的高情商公式》/ \n高情商=满足自己＋成全别人=成事\n我的高情商课程 总结了我过去工作和生活中高情商成事儿的实践经验，28节音频课，从底层认识到行动，教大家成为不仅让自己爽，还能成事儿的人。",
