        "full": "【开场】\n本期《天真不天真》带来「折腾vs独处 极致对照组的两种活法答案」。一档值得关注的播客。\n\n【本期内容叙述】\n本期《天真不天真》播出「折腾vs独处 极致对照组的两种活法答案」。节目延续一贯风格，围绕这一主题层层展开。\n▸ 活着是什么？什么叫“自由的活着”？\n▸ 易老师谈社交恐惧——“Small talk对我来说很恐怖”\n▸ 易立竞：深度人物访谈呈现的不是真相，而是人的复杂性\n▸ 拒绝做采访课的原因是不能辜负被采访者的信任\n▸ 各自的一个月独处：山里荡秋千笑出声来&受尽人间疾苦奔溃大哭\n▸ 天真坐轮椅后的“弱者视角”察觉：物理高度变了，看世界的方式也变了\n▸ “观察着自己的自己又是谁？”关于觉知力、上帝视角，以及人生修行的训练\n▸ 马伊琍的点醒：你讲的都对，但对方一句都听不见\n\n节目没有停留在表面的观点罗列，而是在具体的情境、对话与追问中，把话题真正推进到深处。\n\n【🗣️ 经典对话】\n这一期里，有些话值得反复听：\n\n“Small talk对我来说很恐怖”\n“观察着自己的自己又是谁？”\n“我不想显得对谁很在意”\n“谎言是在人世间行走特别有效的拐杖”\n“人间观察的隐身草”\n\n【深度解读】\n本期主题：「折腾vs独处 极致对照组的两种活法答案」。本期主题：「折腾vs独处 极致对照组的两种活法答案」。本期《天真不天真》围绕「折腾vs独处 极致对照组的两种活法答案」展开。一档值得关注的播客，延续节目一贯的深度与质感。\n\n【核心看点】\n• 当期重点：她是顶尖的深度人物访谈记者，也是我见过最享受独处的人，能在山里一待就是一个月。而我似乎永远在折腾，腿瘸着、被跳蚤咬了一堆包，还能蜷在轮椅上想创业项目。\n\n【为什么值得听】\n延续《天真不天真》一贯的内容水准，值得点开收听完整内容。\n\n【结尾】\n延续《天真不天真》一贯的内容水准，值得点开收听完整内容。",
