        "desc": "故事FM ❜ 第 906 期\n爱哲按：\n1972 年 2 月 21 日，尼克松访华。此后，中美关系逐步改善，中苏关系也趋于缓和，爆发大规模战争的可能性不断降低。国家开始调整三线建设战略，逐步减少新增投资，许多三线企业也进入了「军转民」时期。\n1973 年，914 厂的军代表撤出，工厂也从生产枪管、炮管等军工产品，逐步转向民用钢管生产。1983 年，国务院成立三线调整改造办公室，推动三线企业转型发展。\n然而，真正的考验才刚刚开始。改革开放之后，市场经济迅速发展，曾经依靠计划经济运行的三线企业，不得不第一次直面市场竞争。914 厂，也迎来了建厂以来最艰难的时期。\n本期节目是故事FM 与中国国家地理播客共创的播客节目。\n时间轴：\n02:55-养鸡，养鸭，卖苞米楼子，寻找自救方法\n05:17-工厂效益断崖式下降\n07:57-小学没毕业，中学没了，中学没毕业，高中没了\n09:48-国企转民营体制，断腕般艰难\n11:51-200多人的车间，只留下了44人\n17:50-吉林疫情爆发，全厂齐心渡难关\n21:47-厂三代的回归\n24:19-关于 914 厂的未来\n/Staff/\n讲述者｜李福才 王雅男 柴文军\n主播 |&nbsp;@故事FM 爱哲\n采访 |&nbsp;@故事FM 爱哲&nbsp;\n制作人 |&nbsp;晓橙\n文案整理 |&nbsp;晓橙\n声音设计 |&nbsp;晓橙\n运营 |&nbsp;鸣鸣\n用你的声音，讲述你的故事。故事FM 是一档亲历者自述的声音节目。\n商务合作：bd@storyfm.cn\n微信公众号：故事FM (ID: story_fm)\n新浪微博：@故事FM_StoryFM\n个人微信号：gushi_fm02",
