        "desc": "【主播的话】 \n十几年前，还在读研究生的於嘉向一本知名社会科学期刊投了一篇自己刚写完的论文——关于中国人结婚影响因素的研究。但很快，她收到了拒信。期刊的专家当时认为，选题意义不大，因为中国并不存在所谓的“结婚率下降”的问题。\n十几年过去，这个曾被认为“并不存在”的问题变成了全民的焦虑，牵动了全国甚至是全球的神经。於嘉也从学校里毕业，成为了北京大学光华管理学院的一名老师，专事与婚姻、家庭、人口结构有关的研究。\n婚姻制度已经延续了千年。而於嘉认为，我们当下这一代，或许是人类历史上第一代可以选择“不结婚”的人。人们为什么不结婚了？哪些条件的出现让人们可以选择不婚？对今天的人来说，结婚究竟仍然意味着什么？\n我们的对话从这里开始，聊了很多尖锐又诚实的问题：年轻人还做爱吗？答案是，越来越少了——短视频、游戏、和父母同住，正在悄悄挤压亲密的空间。当机器人可以拥有和真人无异的体温与触感，是男人还是女人，会更愿意选择机器人？人工智能的拟人陪伴，正在如何重塑我们对爱与亲密的想象？而那些在婚姻中沉默的中年人、被遗忘的中间地带——他们的欲望与匮乏，又该由谁看见？\n这是一场关于亲密关系底层逻辑的重新勘探：性、婚姻、家庭，从来不只是私人的事，它们是理解一个时代最诚实的切口。\n於嘉把这些思考，浓缩在了一档付费音频节目里。今年早些在看理想APP已经上线：《爱与怕：当代婚姻的困境与出路》。我们将在本集节目的评论区抽取三名幸运听众，送出这档音频节目的免费收听码。欢迎大家踊跃评论。\n【本期主播】 \n若含 ：小红书@若含\n王磬： 微博@王磬\n【本期嘉宾】 \n於嘉 ：北京大学社会研究中心长聘副教授，看理想《爱与怕：当代婚姻的困境与出路》主讲人\n【本期剧透】 \n04:49 十年前，学术界认为婚姻与家庭是鸡毛蒜皮的小话题，不值得关注\n10:41 研究性与爱的挑战：在“敏感地带”寻找真实数据 \n18:40 这五年里，中国人的性欲望萎缩了吗？\n23:26 男性或女性，会更愿意选择机器人性伴侣？ \n29:25 男女性别观为什么会产生“时差”？\n33:23 “蜜月效应”：全球伴侣进入稳定关系后，激情都会下降\n39:36 超过 1/5 的中年人在过无性生活\n42:50 中国迎来了历史上第一代真正可以主动选择不结婚的人\n49:13 解绑沉重的婚姻 ：单身生育、同居保障，优化离婚程序...\n01:01:01 全球生育率下降是不可逆的吗？\n【相关阅读】 \n《爱与怕：当代婚姻的困境与出路》 \n於嘉老师在“看理想” APP 上推出的音频节目，从社会学、人口学、性别研究等视角出发，依托真实数据与访谈，剖析这个时代真实的婚姻困境，重塑我们对亲密关系的想象。这份指南，给不婚的、犹疑的，以及身在其中的我们，解剖当代婚姻的现实困境，探讨亲密关系中的爱与怕。\n雪儿·海蒂（Shere Hite） \n美裔德国性教育家、女权主义者，生于美国，1995年放弃美国国籍，加入德国籍。著有《海蒂性学报告》等畅销性学读物。雪儿·海特的研究主要是个人的性体验及其意义。她研究的结论是：70%的女性无法通过抽插式性交达到高潮，而如果通过手淫或其他方式直接刺激阴蒂则她们很容易获得高潮\n埃丝特·佩瑞尔（Esther Perel） \n婚恋心理咨询师、《纽约时报》畅销书作家，被认为是现代亲密关系领域最具洞察力和独创见解的人。她精通 9 门语言，在纽约市从事咨询业务，拥有35年的从业经验，并为全球财富500强企业担任组织顾问。著有国际畅销书《亲密陷阱：爱、欲望与平衡艺术》《危险关系：爱、背叛与修复之路》。\n刘达临 \n上海人，北京大学新闻系毕业，上海大学社会系教授，曾任亚洲性学联合会副主席、上海性社会学研究中心主任、中华性文化展览馆馆长，著有《性社会学》《中国性文化史》《世界古代性文化》《世界当代性文化》等一百四十余部著作。\n潘绥铭 \n现任中国人民大学性社会学研究所所长、社会学系教授、博士生导师，中国社会学会副秘书长。1984年毕业于东北师范大学历史系，获历史学硕士学位。曾留学美国，主要从事社会学研究方法、性社会学和性别人类学研究。出版有《神秘的圣火——性的社会学史》《中国性现状》《性，你真的懂了吗？》《存在与荒谬——中国地下性产业考察》《生存与体验》《当代中国大学生的性观念与性行为》《金西报告——人类男性性行为》等。\n【本期音乐】 Kevin MacLeod - Bass Meant Jazz\n【节目制作】 方改则\n【Logo设计】 刘刘（ins: imjanuary)\n【互动方式】 \n小红书@不合时宜\n微博@不合时宜TheWeirdo\n商务合作可发邮件至 hibuheshiyi@126.com 或微博私信\n会员计划咨询可添加微信：hibuheshiyi3 或发送邮件至 hibuhehsiyi@gmail.com",
