        "full": "【开场】\n本期《不合时宜》带来「当婚姻退场、AI降临，我们该如何相爱？」。一档值得关注的播客。\n\n【本期内容叙述】\n本期《不合时宜》播出「当婚姻退场、AI降临，我们该如何相爱？」。节目延续一贯风格，围绕这一主题层层展开。\n▸ 十几年前，还在读研究生的於嘉向一本知名社会科学期刊投了一篇自己刚写完的论文——关于中国人结婚影响因素的研究。但很快，她收到了拒信。期刊的专家当时认为，选题意义不大，因为中国并不存在所谓的“结婚率下降”的问题。\n▸ 十几年过去，这个曾被认为“并不存在”的问题变成了全民的焦虑，牵动了全国甚至是全球的神经。於嘉也从学校里毕业，成为了北京大学光华管理学院的一名老师，专事与婚姻、家庭、人口结构有关的研究。\n▸ 婚姻制度已经延续了千年。而於嘉认为，我们当下这一代，或许是人类历史上第一代可以选择“不结婚”的人。人们为什么不结婚了？哪些条件的出现让人们可以选择不婚？对今天的人来说，结婚究竟仍然意味着什么？\n▸ 我们的对话从这里开始，聊了很多尖锐又诚实的问题：年轻人还做爱吗？答案是，越来越少了——短视频、游戏、和父母同住，正在悄悄挤压亲密的空间。当机器人可以拥有和真人无异的体温与触感，是男人还是女人，会更愿意选择机器人？人工智能的拟人陪伴，正在如何\n▸ 这是一场关于亲密关系底层逻辑的重新勘探：性、婚姻、家庭，从来不只是私人的事，它们是理解一个时代最诚实的切口。\n▸ 於嘉 ：北京大学社会研究中心长聘副教授，看理想《爱与怕：当代婚姻的困境与出路》主讲人\n▸ 十年前，学术界认为婚姻与家庭是鸡毛蒜皮的小话题，不值得关注\n▸ 研究性与爱的挑战：在“敏感地带”寻找真实数据\n\n节目没有停留在表面的观点罗列，而是在具体的情境、对话与追问中，把话题真正推进到深处。\n\n【深度解读】\n本期主题：「当婚姻退场、AI降临，我们该如何相爱？」。本期主题：「当婚姻退场、AI降临，我们该如何相爱？」。本期《不合时宜》围绕「当婚姻退场、AI降临，我们该如何相爱？」展开。一档值得关注的播客，延续节目一贯的深度与质感。\n\n【核心看点】\n• 当期重点：十几年前，还在读研究生的於嘉向一本知名社会科学期刊投了一篇自己刚写完的论文——关于中国人结婚影响因素的研究。但很快，她收到了拒信。\n\n【为什么值得听】\n延续《不合时宜》一贯的内容水准，值得点开收听完整内容。\n\n【结尾】\n延续《不合时宜》一贯的内容水准，值得点开收听完整内容。",
