        "desc": "【本期嘉宾】\n徐新，今日资本创始人。\n高继扬，星海图创始人兼CEO。\n【高能事物】\n科技创新、估值泡沫、泡沫破灭的可能，以及在今天火热的市场中应该做什么。\n【特别鸣谢】\n【内容索引】\n02:03 看新行业最大的错误是只见树木不见森林，要把每棵树都看一遍；见高继扬当天就签了term sheet，上一个是杨植麟\n02:42 学软件的8个月做出本体，改变一个行业的都是外行\n07:04 你们为什么能做硬件，为什么偏要合在一起创业\n10:35 我以为创业已经过了清华北大不如胆子大的阶段了，原来清华毕业的胆子也大\n11:39 Ilya走了以后OpenAI就差点劲了，Anthropic只赌一个方向，赌对了\n15:06 做自动驾驶最大的教训，软件供应商拿不到数据，飞轮跑不起来\n26:02 To B场景其实已经能替人了，只是速度还赶不上人；具身智能也不会有GPT时刻\n30:00 大脑越用越值钱，硬件越造越便宜，所以两个都要做\n31:30 暴涨期get big fast抢到的市占率是永恒的，前提是你得是operating system或infrastructure\n36:08 三年没变的三句话，一脑多形，核心在脑不在形，壁垒是物理世界的数据闭环，路径是整机加智能\n38:46 硬件比软件难多了，bits很容易，atoms很难\n40:13 最大的遗憾是字节早期没投到，你赚不到认知之外的钱；后来一个基金55%的钱重仓美团，底气是铃木敏文那句\"人的天性就是懒惰\"\n46:31 迭代是唯一的护城河\n48:46 具身智能不在任何大厂的直接射程之内\n54:17 招人先算一个公式，5万月薪的人加agent有没有大于agent\n01:00:05 供应链老板们的态度，向往加焦虑\n01:01:14 学得越多越聪明，而不是造得越多越便宜\n01:23:42 泡沫没什么了不起，网易新浪搜狐揣着8000万到1亿美金活下来，三年没有对手；raise money when you can\n01:27:33 决定行业走向的就100到200个人，聚成10堆，我只有9个对手\n01:37:01 投传统行业像登山，投技术像冲浪\n01:38:18 home run强度比频次重要，double down你的winner，拿8到10年赚时间的复利\n01:51:45 九年积累全部推翻，只有founder敢做这种决策\n01:54:01 投资中最危险的五个字是\"这次不一样\"，但是这次真的不一样\n01:58:36 我的风险不是死掉，是错过\n02:08:09 刘强东要200万美金，徐新给了1000万，每年200%增长，从5000万干到100亿，一直亏钱\n02:20:15 跟上一代的差别不在其他，在时势；美团京东那种创业更难，因为可做的人太多了\n02:22:51 行业迅速做大时的心境是什么，这是世界上不流通的信息，所以他看蒋介石日记\n02:28:01 如果每个决策都不算细账，1亿美金原本能训十次，不精细就只能训五次\n02:30:22 怎么区分淘金的人和有使命的人，先看是否知行合一，再看他吸引到的联合创始人\n【往期链接】\nVol.177 从工具、社区到情感大模型与具身智能：与任永亮聊2011、2016和2022几个技术周期中的测测 \n【制作团队】\n主理人：李翔、李丰\n制作及统筹：张英海（13514156656）、峰小瑞（ pr@freesvc.com ）\n如果你喜欢我们的节目，欢迎你分享到更多的地方，也欢迎你在我们的评论区留言交流。",
