        "quotes": [],
        "full": "【开场】\n本期《故事FM》带来「没有了战争，还要面对和平年代的挑战」。一档值得关注的播客。\n\n【本期内容叙述】\n本期《故事FM》播出「没有了战争，还要面对和平年代的挑战」。节目延续一贯风格，围绕这一主题层层展开。\n▸ 1972 年 2 月 21 日，尼克松访华。此后，中美关系逐步改善，中苏关系也趋于缓和，爆发大规模战争的可能性不断降低。国家开始调整三线建设战略，逐步减少新增投资，许多三线企业也进入了「军转民」时期。\n▸ 1973 年，914 厂的军代表撤出，工厂也从生产枪管、炮管等军工产品，逐步转向民用钢管生产。1983 年，国务院成立三线调整改造办公室，推动三线企业转型发展。\n▸ 然而，真正的考验才刚刚开始。改革开放之后，市场经济迅速发展，曾经依靠计划经济运行的三线企业，不得不第一次直面市场竞争。914 厂，也迎来了建厂以来最艰难的时期。\n▸ -养鸡，养鸭，卖苞米楼子，寻找自救方法\n▸ -工厂效益断崖式下降\n▸ -小学没毕业，中学没了，中学没毕业，高中没了\n▸ -国企转民营体制，断腕般艰难\n▸ -200多人的车间，只留下了44人\n\n节目没有停留在表面的观点罗列，而是在具体的情境、对话与追问中，把话题真正推进到深处。\n\n【深度解读】\n本期主题：「没有了战争，还要面对和平年代的挑战」。本期主题：「没有了战争，还要面对和平年代的挑战」。本期《故事FM》围绕「没有了战争，还要面对和平年代的挑战」展开。一档值得关注的播客，延续节目一贯的深度与质感。\n\n【核心看点】\n• 当期重点：故事FM ❜ 第 906 期。1972 年 2 月 21 日，尼克松访华。\n\n【为什么值得听】\n延续《故事FM》一贯的内容水准，值得点开收听完整内容。\n\n【结尾】\n延续《故事FM》一贯的内容水准，值得点开收听完整内容。",
