        "title": "489 失意者与淘金客：陈婉婧谈当代老挝华商的迁徙与陷阱",
        "desc": "- 导语 -\n地处中南半岛内陆的老挝，在不少中国人的认知中，常由冷战记忆、金三角传闻与中老基建项目拼成一幅模糊图景。2016年，陈婉婧第一次前往万象，随后在长期田野调查中，曾以华人中介助理的身份进入当地社群。她发现了当地华人中介、商会、不同移民群体之间的联系与区隔。自20世纪80年代末起，不同境遇的中国人陆续迁徙至此，形成来源多样、处境复杂的移民群体。邵东、邵阳游商如何依托云南亲人的边境通道在当地持续扎根？中国民营承包商为何在层层分包的中老铁路项目中遭遇失败？不同代际的赴老挝华人又怀揣着怎样不同的生存诉求与期待？请听本期嘉宾陈婉婧带来的精彩分享！\n- 本期话题成员 -\n程衍樑（微博@GrenadierGuard2）\n陈婉婧，德国马克斯普朗克社会人类学研究所研究员。\n- 时间轴 -\n02:36 因「一带一路」与中美角力而关注老挝华人\n10:55 冷战、革命与地理闭塞：被冲散的老华侨群体\n12:13 湖南邵阳人在老挝的「链式移民」通道\n17:55 老挝的华人中介生态：淘金叙事与土地投资陷阱\n28:37 新投资客来临、侨务投入增加：华人商会的崛起\n37:38 改开后来老挝的「经济难民」：破产、下岗与不堪回首的往事\n49:34 「我骗你，是你活该」：错过机遇的小生意人与一带一路投资客的心理隔阂\n57:01 香蕉种植园的大浪淘沙：行业经验与短线投机的不同结局\n01:03:15 中老铁路层层分包背后的民营承包商困境\n01:09:51 从吃苦、淘金到躺平：赴老挝华人的心态代际变化\n- 支持我们的赞助商是对我们最好的支持 -\n忽左忽右旅行团又要出发了！这一次，我们将前往坦桑尼亚，在乞力马扎罗山脚下开启东非之旅，探访塔兰吉雷、恩戈罗恩戈罗和塞伦盖蒂，感受东非野生世界的壮阔。再前往桑给巴尔，在石头城与印度洋海岸放慢脚步。本次坦桑尼亚行动，程衍樑将与一位首次参加忽左忽右旅行团的神秘嘉宾共同带队。2026年9月30日至10月11日，如果您有兴趣参与本次坦桑尼亚行动，请关注「忽左忽右leftright」公众号，回复「坦桑尼亚」了解详情，也可以直接添加旅行团小助手微信 hzhyxzs2 咨询报名。\n《忽左忽右》的卖书业务上线了！这次不仅汇集了节目中深入讨论过的书籍，还有主播个人精选书籍，含少量签名版及稀有原版，完整的书目信息及购买方式，前往微信公众号「忽左忽右leftright」，回复「买书」 即可获取。书目将不定期更新，欢迎常来看看。\n- 制作团队 -\n声音设计 hotair\n节目统筹 禾放\n节目运营 小米粒\n节目制作 思钊 Yo\nlogo设计 杨文骥\n- 音乐 -\nDanse Macabre - Busy Strings - Kevin MacLeod\n- 本节目由JustPod出品 © 2026 上海斛律网络科技有限公司 -\n\n- 互动方式 -\n商务合作：ad@justpod.fm \n微博：@忽左忽右leftright @播客一下 @JustPod\n微信公众号：忽左忽右Leftright / JustPod / 播客一下\n小红书：JustPod气氛组 / 忽左忽右\nB站：忽左忽右leftright\n抖音：忽左忽右",
