        "background": "战国中期，七雄并立、兼并战争白热化。秦国偏居西陲，被中原诸侯视为「戎狄」。秦孝公即位后痛感落后，发布求贤令：「宾客群臣有能出奇计强秦者，吾且尊官，与之分土。」商鞅由魏入秦，以「霸道」之说打动孝公，获任左庶长主持变法。",
