        "background": "13 世纪蒙古帝国横扫欧亚大陆，建立起从中国到波斯的「蒙古和平」（Pax Mongolica），陆上丝绸之路空前畅通。1260 年马可·波罗的父亲尼科罗和叔叔马费奥曾到过元朝见过忽必烈，1271 年带着忽必烈的国书再出发，从地中海东岸经两伊、中亚，翻越帕米尔，沿塔里木盆地、河西走廊到达元上都。",
        "event": "1275 年到达元上都开平（今内蒙古正蓝旗），受到忽必烈欢迎。17 年间他游历中国大部分地区，据说在扬州任职 3 年，到过云南、缅甸、东南亚。《游记》记录了大都（北京）的繁华、纸币、煤的广泛使用、驿站制度、瓷器、雕版印刷术。1295 年回到威尼斯，正赶上威尼斯与热那亚的战争，他在 1298 年的海战中被俘，在监狱里口述给狱友鲁思蒂谦诺写下《东方见闻录》。",
        "impact": "《马可·波罗游记》在欧洲引发「东方热」，被译成几乎所有欧洲语言，哥伦布、达·伽马、马基雅维利都读过。虽然书中数字多有夸张，但关于纸币、煤炭、驿站等描述基本属实。它把欧洲人的世界想象从「欧亚非三洲」拓展为「真正的全球」，是「大航海时代」最直接的精神前驱。",
