      "desc": "– 本节目由GIADA出品 –\n【本期制作人】shiyue\n【本期嘉宾】\n芮迺伟，职业棋士\n陈鲁豫，媒体人、主持人\n【本期节目介绍】\n岩中花述第九季第七期，鲁豫遇到四十年前中日围棋擂台赛的女先锋芮迺伟，那曾是她对女棋手的全部想象。\n11岁时走进围棋训练班，芮迺伟很快显露出一种天赋：坐得住。围棋给了那个戴眼镜的孤僻女孩一个可以安放专注力的地方，也让她从赢棋中一点点长出了自信。直至进入国家队，她突然感受到男女棋手机会的悬殊，于是只能说服自己忘掉性别去拼。\n1988年，她升为世界围棋史上首位女子九段。也是那一年，一份训练局年终报告里的“行为不检点”五个字让她决定出走。此后十年，舞台一直在那，她上不去。漫长的等待让她确认了一件事——在棋盘中努力、在赛场上争胜，是自己到了下辈子也想继续的事业。还好，最终她回来了。\n漫长的等待与煎熬后，她说自己幸运——因为能者多助，因为她熬过来了；AlphaGo击败人类世界冠军后，她说感到幸福，因为AI展示了自己没能看到的奥妙，引领着自己继续探索。\n在一盘棋里，只要还有机会，就不能中盘认输。在人生的棋局中，只要还能让自己精进，她就愿意等、愿意守。如今63岁的她还在下职业围棋，最小的对手12岁，是她当年差不多开始学棋的年纪。\n她说：“比起输棋，没有棋下更难受。只要还能比赛，明天的太阳就依旧升起。”\n【内容提要】\nPart 1 上场 \n03:59 围棋让那个孤僻的孩子找到自信\n10:18 走职业道路还是考大学，父母犹豫，我却惶恐回到学校\n12:40 “优势说不出来，劣势很多”——围棋里的性别困境\n19:19 不再把自己当女棋手，要不然就不去幻想能有重要的比赛\n27:55 背负了太多期待而后输棋，就是世界末日的感觉\nPart 2 出走 \n32:50 冲动可以消解一时的压抑，却终归要回到原来的世界\n35:40 1987年的三峡事件——“行为不检点”五个字改变一生\n42:56 大不了不做棋手去上学，可等离开后才发现还是更想下棋\n47:16 命硬需有认死理的品质，也需有命运的眷顾\n51:23 舞台一直在那儿，但我上不去\n55:45 和江铸久异地三年，他从未让我退居幕后\n63:16 沉船的刹那，赶快下棋，那下辈子就还能做棋手\nPart 3 归来 \n68:21 22年后终于回国，能够用母语思考和交流的感觉真好\n71:57 学习师傅吴清源，将围棋作为一生的修行\n76:28 AlphaGo与李世石比赛，人类棋手成为命运共同体\n81:02 赛场年龄差不断增长，学棋的时代在变好\n84:59 走过了三毛去过的许多地方，但还是得有棋啊\n92:02 输棋会慢慢习惯，但只要还能下，就要多享受\n\n– 主题曲 –\n《岩中花述》陈婧霏\n\n– 节目中提及的作品与人物 –\n中日围棋擂台赛，由中国围棋协会、日本棋院和中国《新体育》杂志社联合举办的围棋团体对抗赛，于1984年10月首次举办，至1996年共进行11届，中国队以7比4的总比分获胜。\n应氏杯，由中国台湾企业家应昌期出资创办，中国围棋协会和应昌期围棋教育基金会共同主办的世界级职业围棋个人赛。\n《一盘没有下完的棋》，1982年中日合拍电影，由孙道临、三国连太郎主演。\n罗洗河，中国围棋九段棋手，现任中国围棋甲级联赛深圳龙华队主教练。\n常昊，中国围棋九段棋手，现任中国围棋协会主席。\n华学明，中国围棋七段棋手，先后担任国家围棋队领队、中国围棋协会副主席。\n杨晖，中国围棋八段棋手，前国家围棋队主力。\n聂卫平，中国围棋大师，职业九段，曾任中国围棋协会名誉主席、中国国家围棋队总教练，有“棋圣”称号。\n江铸久，中国围棋九段棋手，曾在第一届中日围棋擂台赛取得五连胜。芮迺伟的丈夫。\n张文东，中国围棋九段棋手，中国首位从初段直升九段的职业棋手，毕业于北京大学历史系。\n俞斌，中国围棋九段棋手，中国国家围棋队总教练。\n张璇，中国围棋八段选手，女子围棋世界冠军。\n柯洁，中国围棋九段棋手，中国围棋史上最年轻的八冠王，曾连续40个月稳居世界等级分第一。2016年与阿尔法围棋展开三番棋对决，均告负。\n郝克强，《围棋天地》《新体育》杂志创刊者，中国围棋协会原副主席，中日围棋擂台赛发起人。\n陈祖德，中国围棋九段棋手，新中国首位击败日本九段棋手的国手，“中国流”布局首创者，中国棋院首任院长。\n吴清源，被誉为“昭和棋圣”“十番棋之王”的围棋大师，其提出的“21世纪的围棋——六合之棋”开创了现代围棋新时代。\n曹薰铉，韩国围棋九段棋手，职业生涯夺得九个世界冠军，有“围棋皇帝”之称，培养了“石佛”李昌镐。\n车敏洙，韩国围棋五段棋手、职业扑克选手，赴美发展，曾任韩国职业棋士会会长。\n李世石，韩国围棋九段棋手，职业生涯中14次世界比赛冠军，也是唯一战胜过AlphaGo的人。\n大竹英雄，日本围棋九段棋手，别称“美学棋士”。\n加藤正夫，日本围棋九",
      "pub": "Wed, 05 Aug 2026 00:00:00 GMT",
      "link": "https://www.xiaoyuzhoufm.com/episode/6a719a98ab3a91c24a0f95e2?utm_source=rss",
