        "「关注投资，更关注怎样更好地生活」是它的底色：钱的问题最后都指向人的选择与心态，这也是它长期位居财经前列的原因。当期重点：一个多月前，我和家里长辈闲聊，她突然特别严肃地问我： “你知道吗？那个谁谁谁说，今年年底会发生一场全球性的金融危机，规模堪比 2008 年” ，我非常惊讶，问她是从哪里听说的，结果聊了半天，她也没说清楚这个人到底是干嘛的，更不知道他怎么推导。"
