      "desc": "主播 | 潇磊 刘飞\n————\n2026年7月25日，“景德镇手工瓷业遗存”被列入《世界遗产名录》。\n本期节目，我们沿着昌江与窑火，复盘景德镇的千年商业沉浮：\n· 从青白瓷、元青花到御窑厂：景德镇怎样靠原料、航运、海外订单和宫廷标准，从众多窑口中脱颖而出？\n· “过手七十二，方克成器”：一座没有总厂的手工业城市，如何靠高度分工、行帮规则和柔性协作组织起庞大生产链？\n· 从欧洲“瓷器病”、龙骑兵瓶到近代机器工业冲击：当欧洲学会烧瓷，景德镇为何陷入漫长转型？\n· 从珠山八友、十大瓷厂到煤烧隧道窑：个人署名如何改变瓷器价值，新中国又怎样重新组织这座城市？\n· 当国营大厂倒下，“大师”头衔如何抬头，又如何卷入代笔、炒作与雅贿，最终在反腐风暴中阶段性退潮？\n· 旧厂房、市集、直播电商和“景漂”怎样把景德镇重新点亮；在文旅、手工艺和先进陶瓷之间，它又面对怎样的新机会与新问题？\n坐吧，来杯半拿铁，我们边喝边唠。（ChatGPT总结的）\n————\n潇磊、刘飞的声音已授权给豆包、剪映等字节系产品使用若干年。\n在视频平台看到的无真人出镜、用我们的音色生成的 AI 内容，均非我们制作。\n————\n�听友投稿邮箱：bannatie@163.com\n️杭州特调「芝麻·半拿铁」的品尝地：西湖区华星路 【01coffee】\n️上海特调「米乳·半拿铁」的品尝地：前滩公园巷 【彼屯 between 自然商店】\n�半拿铁周边购买淘宝店：小羊商店Sheepedia \n� 半拿铁周边之：《人工智能风云录》纸质书，可在各大电商平台购买\n————\n时间轴： \n01:50 千年瓷都景德镇的历史起源\n15:42 元青花的缘起与景德镇制瓷工艺的演变\n36:57 景德镇瓷器的分布式生产\n48:20 景德镇瓷业江湖与行业潜规则\n57:59 景德镇瓷器的官民合作\n01:18:03 欧洲瓷器的发展兴起与景德镇兴衰\n01:35:57 景德镇近代陶瓷工业转型与艺术革新\n01:47:45 . 建国后景德镇陶瓷工业的恢复\n02:05:35 改革开放之后景德镇陶瓷的市场化困境\n02:11:38 景德镇大师瓷、艺术瓷的浮沉与转型\n02:31:57 景德镇的文化与经济现状\n02:53:43 读评论\n\n青白瓷： \n中国国家博物馆元青花龙纹罐： \n大维德瓶： \n大维德瓶颈部铭文： \n水碓 duì ： \n匣钵： \n龙骑兵瓶： \n隧道窑： \n无语菩萨： \n主要参考资料： \n\n《明清景德镇城市经济研究》 梁淼泰 江西人民出版社\n\n《近代景德镇瓷业社会的多维冲突和秩序重构：1903—1949》 李松杰 中国社会科学出版社\n\n《明清景德镇瓷业发展与窑柴的应对》 郭建晖 林俊杰 故宫博物院院刊\n\n《The City of Blue and White: Chinese Porcelain and the Early Modern World》 Anne Gerritsen Cambridge University Press\n\n《China’s Porcelain Capital: The Rise, Fall and Reinvention of Ceramics in Jingdezhen》 Maris Boyd Gillette Bloomsbury Academic\n\n《Re-sourcing Fuels for Ceramic Kilns in Socialist China, 1950s–1980s》 Kaijun Chen History of Science\n\n《The Pilgrim Art: Cultures of Porcelain in World History》 Robert Finlay University of California Press\n\n《永远在路上》第四集《利剑出鞘》 中央纪委宣传部 中央电视台\n\n《景德镇：中国瓷业的近代印迹——商品瓷与职业化经营的变迁》 罗苏文 史林\n\n《景德镇陶瓷史稿》 江西省轻工业厅陶瓷研究所 生活·读书·新知三联书店\n\n《千年瓷都景德镇：危机与突围》 崔银娜 民生周刊\n\n《陶溪川：青年“造梦厂”》 黄浩然 陈浚武 瞭望新闻周刊\n\n《瓷器故事里的兴衰启示》 郝薇薇 环球杂志\n\n《再访“瓷都”：大师的幻灭》 郭芳 中国经济周刊\n\n《瓷器的官场生意》 郭芳 简文超 中国经济周刊\n\n等\n————\n片尾曲：\n普阿山《没有个性的人》选段\n本期制作：\n张超辉\n封面图及摘要：\nChatGpt",
