      "desc": "本期主播：六兽、贾行家（得到app总编辑、作家）\n本期嘉宾：六神磊磊（本名王晓磊，曾任新华社重庆分社记者，著有《六神磊磊读金庸》《给孩子的唐诗课》等）\n本期是我们的新栏目【趣聊名著】的第一期（大概率叫这个名，可能以后还会改但不重要大概就是这意思吧），我们凑齐了俩六老师+一个行家，来聊聊文学名著《红楼梦》！提到《红楼梦》，就离不开「解读」二字，一部越品越值得品的文学名著，还有哪些角度刁钻的有趣解读？我们今天就来好好聊聊！本期包含以下内容——\n-六神磊磊起心动念写《读红楼》，是因为一个“批评”？\n-写书小插曲：《红楼梦》和《读红楼》都“丢文稿”啦？\n-几位小时候第一次看《红楼梦》的经历：从瞎翻、到小人书 连环画\n-震惊！原来《红楼梦》的大结局其实是贾府一起包饺子？看懂的都哭了！\n-很多人没读完《红楼梦》，但对《红楼梦》的印象又是哪里来的呢？\n-辣评剧版《红楼梦》！六神磊磊：来的时候你们说 在这里可以随便说的呀～\n-每个人读《红楼梦》，都是带着自己的人生经验来读的\n-《红楼梦》是像镜子一样的小说，大家在里边照见的，其实都是自己\n-贾母拥有稻香村同款营销策略？贾府里的人生病可能是颜料中毒？\n-林黛玉，究竟是阴阳怪气还是性格直爽？\n-聊聊《红楼梦》人物的mbti！i人代表、e人代表、j人代表分别是？\n-聊聊《红楼梦》里的职场心理学！\n-纯个人喜好！六神磊磊老师和贾行家老师最喜欢的《红楼梦》角色是哪个？\n-希望大家都能像鸳鸯一样活得舒展、自在！\n-《红楼梦》里有没有什么冷门的角色是被低估的？\n-六神磊磊老师和贾行家老师读这么多遍《红楼梦》的不同感受？\n-广告时间到！夸夸《读红楼》这本书！\n欢迎收听本期播客，也欢迎大家一起读一读六神磊磊新书《读红楼》！这是一本解读《红楼梦》故事和人物的书。六神磊磊以独特的视角和风格，带领你贴近文本，贴近生活，贴近人的情感去读红楼。书中所有关于情节和人物的分析都基于文本，不做过度的臆想和猜测。从人物的内心出发，分析人性、情怀、经验。对人性不做任何高估，对人的不完美也不轻易进行诋毁。\n插播两条最直白！最简单！最不绕弯子的广告！\n刘旸教主单口喜剧专场《身心俱疲》正在全国巡演中！期待与大家剧场相见！\n刘旸教主个人微综艺《死肌肉大挑战！》现已在b站独家上线！究竟是死肌肉还是活肌肉？一看便知！欢迎大家移步b站观看（记得给教主一键三连哟～）\n【关于我们】\n🎬收看无聊斋视频内容？关注微博、小红书、B站、抖音：@无聊斋\n🙋投稿成为无聊斋嘉宾？公众号关注「无聊斋」回复“投稿”\n👀来参与线下录制？公众号关注「无聊斋」会有不定期观众招募掉落\n👗想加入无聊斋听友群？关注 @无聊斋 小红书，加入首页听友群\n🤝商务合作？欢迎发送邮件至 luckylikeu@163.com \n✍️制作：婧文\n✂️剪辑：小天",
      "pub": "Wed, 05 Aug 2026 16:00:00 GMT",
      "link": "https://www.xiaoyuzhoufm.com/episode/6a72f2451b5e24969ce9530a?utm_source=rss",
