      "desc": "本期节目我们读长篇小说《油炸绿番茄》，作者范妮·弗拉格。\n\n《油炸绿番茄》出版于1987年，出版即畅销近40年。小说采用双线叙事：1980年代的伊夫琳和妮妮，与1930年代的艾姬和露丝，交叉书写。叙事杂而不乱，利用妮妮的回忆、汽笛镇《小镇新闻简报》和全知视角三种形式，相互补充，将一幅美国南方乡镇风土日常的画卷徐徐展开。与时代紧密结合，探讨了家庭、衰老、女性友谊及种族主义等主题。由作者亲自参与编剧的同名改编电影于1991年上映，获两项奥斯卡奖提名。\n\n范妮·弗拉格（1944-），美国作家。本名帕特里夏·尼尔，生于阿拉巴马州伯明翰。14岁开始演剧，曾六次参加阿拉巴马小姐选美并获奖学金。19岁起担任编剧并制作、参演电视节目。获2012年哈珀·李奖。弗拉格是性少数群体，1970–80年代曾为ERA（《平等权利修正案》）助选，她当时的伴侣、作家丽塔·梅·布朗是激进女权运动的旗帜人物。\n\n你会听到：\n1、小说的主要故事情节及作者简介。\n2、介绍小说中两条时间线涉及的时代背景，如铁路发展、3k党、南北方经济、女权主义。\n3、如何理解1980年代时间线中“伊芙琳”的角色设置？汽笛镇的故事如何治愈和改变她？小说的叙事结构对阅读体验有哪些影响？\n4、精彩片段分享。\n\n片头曲：上天桥\n片尾曲：Moon River - Andy Williams\n\n主播：超哥 / 星光 / 大壹",
