      "desc": "【主播】 \n\n@晓卉是一枝花\n\n@单口喜剧石老板\n\n@王继业啊\n\n@刘仁铖真不错\n\n@午夜骑手毛冬\n\n欢迎收听「未来生活指南」最终章——上海篇。\n\n时隔两年《基本无害》再次回到上海录制还是会被上海朋友们的实力和规划能力震撼，在听到上海朋友们不上班的一天之前我们简直是在乱做未来计划（不是\n\n温馨提示：结尾有基本无害小惊喜拾取方式。\n感谢华夏基金对本期基本无害的支持！ \n\n作为国家支持的第三支柱养老保障，个人养老金是社保养老金的重要补充，能帮我们多一份养老保障。 华夏基金 旗下适配个人养老金账户的指数类Y份额基金专为个人养老金设计，费率更具优势，依托华夏基金强大的指数管理能力，精准跟踪对应指数走势，聚焦长期养老目标，兼顾安全性与收益性，助力投资者科学规划养老资产，大家可以到招商银行App搜索\" 尽兴养老 \"了解详情。\n\n*市场有风险，投资需谨慎，请大家谨慎了解评估风险后再投资。\n【内容提要】 \n\n00:00:59 阵容介绍\n\n00:04:20 身份牌选择\n\n00:09:49 要不要去火星探索\n\n00:16:39 关于硅基团队的项目介绍\n\n00:21:37 主播们对未来的整体态度\n\n00:25:27 一杯红酒配电影～\n\n00:31:04 「我连饭都吃不下去」「那真是完蛋了」\n\n00:35:39 有没有哪一刻觉得自己老了\n\n00:48:28 不工作的人是什么状态？\n\n01:11:33 高能量沪女提前退休的一天\n\n01:16:34 刘仁铖典型的一天\n\n01:24:53 大家为来退休做了哪些财务上的准备\n\n【音乐】 \n\n借过一下！—— Matt吕彦良\n\n蘇州河 —— 雷玖陆\n\n进听友群： 添加微信号：jibenwuhai2024，小助手Marvin会拉你进群\n\n看视频版： 在 小红书 、 微博 、抖音、 B站 搜索账号 @基本无害\n\n主播日常： 在 小红书 、 微博 、抖音、 B站 搜索账号 @午夜骑手毛冬\n\n制作：枳壳er\n\n剪辑：Klynn、枳壳er\n\n运营：Marvin\n\n封面设计：张透明\n\n【商务合作】 \n\n微信：jibenwuhai2024，备注「播客合作」\n\n邮箱：mostlyharmlessfm@gmail.com",
