      "title": "vol.1417 拿了美国籍又回国，我遇见的奇葩何止99个",
      "desc": "拥有多年潮流服装从业经验的囍子做客节目，从海外行业壁垒聊到国内职场沉浮，再到实体创业的血泪教训。东北出身的他远赴美国求学定居，坐过兰博基尼的副驾，也体验过被警察拿枪顶住后脑勺的绝望。被美国职场边缘化后，他毅然回国，本以为能大展拳脚，却接连遭遇项目解散、老板一夜改赛道、内部派系斗争被裁员。不甘心的他转身创业，开设计工作室、投资瑜伽馆、理发店、做帽子品牌，结果全线亏损。如今40岁重返职场，猎头一句“履历太跳”让他卡在高不成低不就的尴尬关口，满是中年人的无奈与心酸，而划水怪又是怎么看待这场“危机”的呢？\n\n更多精彩内容，欢迎收听本期节目~\n\n主播 / 相征&nbsp;\n\n嘉宾 / 囍子\n\n音频后期 / 陆凯BBBBUDDHA\n\n音频上传 / 恬恬\n\n-本节目由深夜谈谈 Midnight Network出品 -\n\nTimeline\n\n00:04:03 加入美国国籍经历&nbsp;\n\n00:09:20 兰博基尼之“速度与激情”\n\n00:24:38 美国经济现状\n\n00:38:27 波特兰、纽约之行\n\n00:46:33 美国生活成本激增！\n\n00:49:52 小费的委屈\n\n00:52:03 斩杀线与华人消费观念的差异&nbsp;\n\n01:00:39 移民设计师的职场挑战\n\n01:03:55 刚加入就散了？！\n\n01:15:17 职场派系斗争导致高级总监被裁&nbsp;\n\n01:26:46 商学院学习之旅\n\n01:34:40 于是开始创业了！\n\n01:43:03 有故事的拉面店主\n\n01:50:03 40岁后职业选择难题&nbsp;\n\n01:59:24 JAY-Z,Linkin Park - Points of Authority / 99 Problems / One Step Closer\n\n恰逢周年，大内十三周年限定主题周边正式上线。在香港的俚语里，“My Cup Of Tea”代表合心我意、投缘，于是我们将Tea替换成T恤的缩写Tee，于是就有了“MY CUP OF TEE 係我杯茶”的周年主题。而本次周边分为是定制马克杯、主题T恤两款单品，也推出了成套纪念礼盒（礼盒附赠随机主播签名嗷）～\n\n藏式金刚断烦恼，紫檀咒珠守心安。二十八宿催红鸾，甲子莲蓬伴流年。大内上新四款手串，愿你遇事不慌，少些内耗，遇见真心，白首不离。微信搜索小程序“大内夜市”，把祝福戴在腕间，日子自有光亮。\n\n奔赴天山下的阿拉木图，给自己放个假！Gorillaz、Jack White 等传奇乐队轮番开唱。划水怪&amp;miya带队大内专属小团，雪山峡谷、实弹射击、湖畔晚餐尽收眼底。2026.08.20-08.25​，诚邀你用旷野与音乐清空焦虑，共赴一场线下出逃，重置紧绷一整年的身心。​微信搜索小程序“大内夜市”，即可报名～​\n\n深夜谈谈招聘啦，本次开放岗位\n\n全职：1、视频编导（北京/上海）&nbsp;2、商务BD&amp;AE （上海）\n\n感兴趣的朋友们请发送求职信+简历+个人作品请发送至邮箱jobs@midnightalks.com\n\n-你还可以在这里找到我们：\n\n小红书：@深夜谈谈、@相征terry、 @miya\n\nB站：@大内密谈midnightalks\n\n视频号&amp;抖音：@深夜谈谈\n\n微博：@大内密谈\n\n微信公众号：大内密谈\n\n商务合作邮箱：biz@midnightalks.com\n\n加听众群：加深夜谈谈子微信（微信号:SYTT-midnightalks2）并回复【听众群】即可进群。",
