        "one": "人会下意识寻找支持自己观点的证据，忽略相反的信息。",
        "concept": "确认偏误指我们倾向于注意、记住、相信那些符合既有信念的信息，而对反例视而不见。它让你越想越觉得自己对。",
        "why": "大脑为节省能量，默认用已有框架解释世界；承认错误会带来认知失调的痛苦，于是系统自动过滤掉不舒服的证据。",
